# frozen_string_literal: true

require 'spec_helper'
require 'runar/sdk'
require 'json'

# N-296 — cross-tier rule for an explicit Sig in a merge's per-input args
# (additional_contract_input_args): a Sig slot the primary call left
# auto-signed (nil) is ALWAYS signed by the connected signer for each
# additional contract input; a caller-supplied value in that slot is
# overwritten (TS reference).
#
# Proves: on the inputs of conformance/sdk-call/stateful-merge-prepared.json,
# call with (a) no per-input args and (b) an explicit garbage Sig in the
# per-input args broadcasts a tx byte-equal to REFERENCE_TX_HEX (derived by the
# TS SDK, Spend-validated on all three inputs by its MockProvider).
# Does not prove: the other tiers (own tests, same constant), non-Sig slots,
# or a live node.
# rubocop:disable RSpec/DescribeClass
RSpec.describe 'N-296 — merge per-input Sig override' do
  # rubocop:enable RSpec/DescribeClass
  vector_path = File.expand_path('../../../../conformance/sdk-call/stateful-merge-prepared.json', __dir__)
  reference_tx_hex = ''

  def n296_utxo(h)
    Runar::SDK::Utxo.new(txid: h['txid'], output_index: h['outputIndex'], satoshis: h['satoshis'], script: h['script'])
  end

  define_method(:merge_tx) do |per_input_args, fee_rate = nil|
    v = JSON.parse(File.read(vector_path))
    art = Runar::SDK::RunarArtifact.from_hash(v['artifact'])
    signer = Runar::SDK::LocalSigner.new(v['privKeyHex'])
    provider = Runar::SDK::MockProvider.new
    provider.set_fee_rate(fee_rate) if fee_rate
    provider.add_utxo(signer.get_address, n296_utxo(v['fundingUtxo']))
    cu = n296_utxo(v['contractUtxo'])
    eu = n296_utxo(v['extraContractUtxo'])
    provider.add_contract_utxo(cu.script, cu)
    provider.add_contract_utxo("#{eu.script}:extra", eu)
    contract = Runar::SDK::RunarContract.from_utxo(art, cu)
    opts = Runar::SDK::CallOptions.new(additional_contract_inputs: [eu],
                                       additional_contract_input_args: per_input_args,
                                       new_state: { 'count' => 1 })
    contract.call(v['method'], [nil], provider, signer, opts)
    txs = provider.get_broadcasted_txs
    expect(txs.length).to eq(1)
    txs[0]
  end

  it 'default (no per-input args) path matches the reference tx' do
    expect(merge_tx(nil)).to eq(reference_tx_hex)
  end

  it 'an explicit non-zero Sig in the per-input args is overwritten by the signer' do
    expect(merge_tx([['ab' * 71]])).to eq(reference_tx_hex)
  end

  # Fee sizing for a merge: at 1000 sat/kB every byte the fee layout misses is a
  # satoshi under-paid. Each additional contract input's unlock carries
  # _changeAmount, so it must be sized with the real change, not 0 (the defect
  # the Java tier had; ported here as a cross-tier pin).
  it 'the merge fee covers every byte of the signed tx at 1 sat/byte' do
    raw = [merge_tx(nil, 1000)].pack('H*').bytes
    varint = lambda do |i|
      n = raw[i]
      next [n, i + 1] if n < 0xfd

      w = { 0xfd => 2, 0xfe => 4, 0xff => 8 }[n]
      [raw[i + 1, w].each_with_index.sum { |b, k| b << (8 * k) }, i + 1 + w]
    end
    n_in, i = varint.call(4)
    n_in.times do
      sl, i = varint.call(i + 36)
      i += sl + 4
    end
    n_out, i = varint.call(i)
    out = 0
    n_out.times do
      out += raw[i, 8].each_with_index.sum { |b, k| b << (8 * k) }
      sl, i = varint.call(i + 8)
      i += sl
    end
    v = JSON.parse(File.read(vector_path))
    paid = v['contractUtxo']['satoshis'] + v['extraContractUtxo']['satoshis'] + v['fundingUtxo']['satoshis'] - out
    expect(paid).to be >= raw.length
  end
end
